VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.83,"Phase eight. Cryptography and blockchain. This is how secrets and trust work online."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":20.016,"caps":[[1.21,5.7,"Anything on the open wire, Eve can read."],[5.95,13.96,"The key is 5: each letter moves 5 along, so S becomes X."],[14.21,19.1,"But how does Bob get the key without Eve seeing it?"]],"warp":[[0,0],[1.21,2.2],[5.95,5.1],[14.21,9.2],[20.016,11.4]]},{"dur":25.008,"caps":[[0.66,4.51,"Both start with the same public paint."],[4.76,7.65,"Each adds a secret paint of their own."],[7.9,12.23,"They swap the mixtures. Eve can see those."],[12.48,17.05,"Each adds their own secret again: the very same colour."],[17.3,19.87,"That colour is their shared key."],[20.12,23.89,"Eve cannot unmix paint to find a secret."]],"warp":[[0,0],[0.66,1.2],[4.76,3.6],[7.9,6],[12.48,8],[17.3,9.7],[20.12,11.1],[25.008,13.4]]},{"dur":36.664,"caps":[[0.69,6.54,"Like the paint: p and g are public, a and b secret."],[6.79,13.6,"mod 23 keeps only the remainder after dividing by 23."],[13.85,18.18,"They swap A = 8 and B = 19 in public."],[18.43,21.56,"Each raises what they received to their own secret."],[21.81,25.74,"Both get 2: a shared key that was never sent."],[25.99,29.92,"Eve must try every power of 5 until she hits 8: that finds a."],[30.17,35.22,"With a 617-digit prime that search is hopeless."]],"warp":[[0,0],[0.688,1.25],[6.787,3.9],[13.848,6.2],[18.428,8],[21.808,9.5],[25.988,11.65],[30.168,13.7],[36.664,15.65]]},{"dur":33.321,"caps":[[0.5,4.91,"Pick two secret primes: 5 and 11."],[5.16,9.17,"Multiply them: n = 55 is public."],[9.42,14.63,"Next z = (5 − 1) × (11 − 1) = 40, kept secret."],[14.88,19.93,"Pick e = 3: only 1 divides both 3 and 40."],[20.18,26.27,"d = 27, because 3 × 27 = 81 = 2 × 40 + 1."],[26.52,32.69,"Publish (55, 3). Keep 27 secret."]],"warp":[[0,0],[0.5,0.5],[5.16,2.4],[9.42,4.1],[14.88,6.5],[20.18,9],[26.52,11],[33.321,13.5]]},{"dur":30,"caps":[[0.55,5.92,"Bob shares his public key, (55, 3)."],[6.17,10.26,"Alice locks 7 with it and gets 13."],[10.51,15.48,"Bob unlocks 13 with his private key: back to 7."],[15.73,19.42,"Eve factors the tiny n in four tries: 5 × 11."],[19.67,23.6,"Then z = 40 and d = 27: she has the key."],[23.85,28.82,"A real n has 617+ digits: nobody can factor that."]],"warp":[[0,0],[0.55,1],[6.17,3.4],[10.51,5.8],[15.73,7.8],[19.67,9.6],[23.85,11.2],[30,13.4]]},{"dur":23.336,"caps":[[0.5,4.51,"New question: was this data changed?"],[4.76,9.25,"A hash turns data into a short fingerprint."],[9.5,14.07,"The same data always gives the same fingerprint."],[14.32,18.65,"Change one letter, the whole fingerprint changes."],[18.9,22.51,"And you cannot work backwards from it."]],"warp":[[0,0],[0.5,0.3],[4.76,1.95],[9.5,4.1],[14.32,7],[18.9,9.1],[23.336,11.1]]},{"dur":26.772,"caps":[[0.55,4.88,"Each block stores the hash of the block before it."],[5.13,9.7,"Edit one block and its hash changes."],[9.95,14.44,"The next block holds the old hash: the link breaks."],[14.69,20.06,"Eve recomputes each later hash to repair the links."],[20.31,25.6,"It looks valid again, but hashes only spot edits."]],"warp":[[0,0],[0.55,1],[5.13,3.3],[9.95,5.5],[14.69,7.9],[20.31,10.8],[26.772,12.5]]},{"dur":30.117,"caps":[[0.5,6.19,"Try numbers (nonces) until the hash starts with 0."],[6.44,11.73,"Every try gives a new, unpredictable hash."],[11.98,14.95,"Found it after 15 hashes."],[15.2,17.77,"Checking takes just 1 hash."],[18.02,22.19,"One hash in 16 starts with 0."],[22.44,28.69,"Two zeros: 1 in 256, so 16 times more work."]],"warp":[[0,0],[0.5,0.4],[6.44,2.6],[11.98,6],[15.2,7.3],[18.02,9],[22.44,11],[30.117,13.5]]},{"dur":25.193,"caps":[[0.5,4.19,"Each block is sealed by its own proof of work."],[4.44,7.89,"Edit block 1: its seal and the link both break."],[8.14,11.83,"Forging it means mining block 1 again."],[12.08,15.85,"Then every later block must be mined again too."],[16.1,23.47,"Rewriting history means redoing all that work."]],"warp":[[0,0],[0.5,0.5],[4.44,2.9],[8.14,4.3],[12.08,5.9],[16.1,8.5],[25.193,11.5]]},{"dur":15,"caps":[],"warp":[[0,0],[0.5,0.9],[4.36,2],[8.78,3.1],[15,9]]}]};
